def transform(grid):
    band = len(grid) // 4
    width = len(grid[0])
    out = [[0] * width for _ in range(band)]
    for layer in (2, 3, 1, 0):
        for r in range(band):
            for c in range(width):
                value = grid[layer * band + r][c]
                if value:
                    out[r][c] = value
    return out
